code='''
function schemeMarkup(t){const s=t.scheme;if(!s||!s.arms?.length)return '<div class="flow-section" id="scheme"><h3>研究方案</h3><div class="data-limit">结构化流程图尚未补齐；请以以下原始方案描述与引用为准。<br>'+esc(t.arms)+'</div></div>';return '<section class="flow-section" id="scheme"><h3>研究方案</h3><div class="flow-pop"><strong>入组人群</strong><br>'+esc(s.population||t.patientGroup)+'</div><div class="flow-alloc">↓ '+esc(s.allocation||t.design)+' ↓</div><div class="flow-arms">'+s.arms.map(a=>'<div class="flow-arm"><h4>'+esc(a.label)+'</h4><ol>'+a.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></div>').join('')+'</div><div class="flow-end">主要终点：'+esc(s.primaryEndpoint||t.primaryEndpoint)+'</div>'+(s.sourceUrl?'<a class="source-link" href="'+esc(s.sourceUrl)+'" target="_blank" rel="noopener noreferrer">方案原始来源 ↗</a>':'')+'</section>'}
function chartMarkup(t){const charts=t.resultCharts||[];return '<section class="chart-section" id="charts"><h3>关键结果 · 原始研究内比较</h3>'+(charts.length?'<div class="chart-grid">'+charts.map(c=>{let svg='';const arms=(c.arms||[]).filter(a=>Number.isFinite(a.value));if(arms.length&&c.type!=='hazard_ratio'){const max=c.unit==='%'?100:Math.max(1,...arms.map(a=>Math.max(a.value,a.ciHigh||0)))*1.2;const W=520,L=30,R=490,H=arms.length*69+32;svg='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(c.title)+'">';arms.forEach((a,i)=>{const y=12+i*69,x=L+a.value/max*(R-L);svg+='<text x="30" y="'+(y+3)+'" font-size="12" fill="#5b7350">'+esc(a.label)+'</text><rect x="30" y="'+(y+14)+'" width="460" height="17" rx="4" fill="#edf2e8"/><rect x="30" y="'+(y+14)+'" width="'+Math.max(0,x-L)+'" height="17" rx="4" fill="'+(i===0?'#679563':'#b6c4a5')+'"/><text x="490" y="'+(y+3)+'" text-anchor="end" font-size="12" fill="#31582b">'+esc(a.value)+' '+esc(c.unit)+(a.n!=null?' (n='+esc(a.n)+')':'')+'</text>';if(Number.isFinite(a.ciLow)&&Number.isFinite(a.ciHigh)){const lo=L+a.ciLow/max*(R-L),hi=L+a.ciHigh/max*(R-L);svg+='<line x1="'+lo+'" x2="'+hi+'" y1="'+(y+22)+'" y2="'+(y+22)+'" stroke="#274b24" stroke-width="2"/><line x1="'+lo+'" x2="'+lo+'" y1="'+(y+16)+'" y2="'+(y+28)+'" stroke="#274b24"/><line x1="'+hi+'" x2="'+hi+'" y1="'+(y+16)+'" y2="'+(y+28)+'" stroke="#274b24"/><text x="30" y="'+(y+47)+'" font-size="10" fill="#819075">CI '+esc(a.ciLow)+'–'+esc(a.ciHigh)+'</text>'}else if(a.ciLow!=null||a.ciHigh!=null){svg+='<text x="30" y="'+(y+47)+'" font-size="10" fill="#819075">CI '+esc(a.ciLow??'下限见来源')+'–'+esc(a.ciHigh??'上限见注释')+'</text>'}});svg+='<text x="30" y="'+(H-4)+'" font-size="10" fill="#96a58b">0</text><text x="490" y="'+(H-4)+'" text-anchor="end" font-size="10" fill="#96a58b">'+(Math.round(max*10)/10)+' '+esc(c.unit)+'</text></svg>'}else if(Number.isFinite(c.hr)){const lo=c.hrCiLow,hi=c.hrCiHigh;const min=Math.min(.25,c.hr,lo||c.hr)/1.2,max=Math.max(2,c.hr,hi||c.hr)*1.2;const x=v=>35+(Math.log(v)-Math.log(min))/(Math.log(max)-Math.log(min))*450;svg='<svg viewBox="0 0 520 145" role="img" aria-label="'+esc(c.title)+'"><line x1="35" x2="485" y1="75" y2="75" stroke="#d7e0cd"/><line x1="'+x(1)+'" x2="'+x(1)+'" y1="20" y2="115" stroke="#a7b39b" stroke-dasharray="4"/>'+(lo!=null&&hi!=null?'<line x1="'+x(lo)+'" x2="'+x(hi)+'" y1="75" y2="75" stroke="#56814b" stroke-width="3"/>':'')+'<circle cx="'+x(c.hr)+'" cy="75" r="7" fill="#56814b"/><text x="'+x(c.hr)+'" y="48" text-anchor="middle" font-size="16" fill="#36562b">HR '+esc(c.hr)+'</text><text x="'+x(1)+'" y="132" text-anchor="middle" font-size="11" fill="#869679">1.0</text><text x="35" y="132" font-size="10" fill="#869679">HR（对数刻度）</text></svg>'}return '<article class="result-chart"><h4>'+esc(c.title||c.endpoint)+'</h4><div class="chart-meta">'+esc(c.timepoint)+' · '+esc(c.population)+'</div>'+svg+'<div class="chart-effect">'+(Number.isFinite(c.hr)?'HR '+esc(c.hr)+(c.hrCiLow!=null&&c.hrCiHigh!=null?'（CI '+esc(c.hrCiLow)+'–'+esc(c.hrCiHigh)+'）':''):'原始报告绝对值')+(c.pValue?' · P '+esc(c.pValue):'')+'</div><p class="chart-note">'+esc(c.note||'误差线仅在来源报告区间时显示；缺失区间不补算。')+'</p><a class="source-link" href="'+esc(c.sourceUrl)+'" target="_blank" rel="noopener noreferrer">数据来源'+(c.sourceDate?' · '+esc(c.sourceDate):'')+' ↗</a></article>'}).join('')+'</div>':'<div class="data-limit">本条尚无适合绘图的已核实数值。保留文字结果，不据摘要重建生存曲线。</div>')+'</section>'}
'''
